fn pathEffect(t: f32, total_arc_len: f32, w: f32, col: vec4f) -> vec4f {
    var c = col;
    c = _pe_stage_0(t, total_arc_len, w, c);
    c = _pe_stage_1(t, total_arc_len, w, c);
    return c;
}

import { PathEffect, Color } from "retiam";

// Accumulate: Gradient -> Neon Glow -> Dashed Pattern
const stroke = PathEffect.Gradient([
    new Color(0.1, 0.9, 1.0, 1.0), // Neon Cyan
    new Color(0.9, 0.1, 0.8, 1.0)  // Hot Magenta
])
.Glow(0.35)
.Dashed(0.5, 0.2);

// Standalone compilation to raw WGSL string:
const wgslCode: string = stroke.compile();

import { PathEffect, Color } from "retiam";

const gradientEffect = PathEffect.Gradient([new Color(1, 0, 0), new Color(0, 0, 1)]);
const glowEffect = PathEffect.Glow(0.4);
const dashEffect = PathEffect.Dashed(0.6, 0.3);

// Standalone merger into one single PathEffect
const cascaded = PathEffect.combine([gradientEffect, glowEffect, dashEffect]);

import { FillEffect, Color } from "retiam";

const checkerboard = FillEffect.Checkerboard(
    new Color(0.15, 0.15, 0.15, 1.0),
    new Color(0.25, 0.25, 0.25, 1.0),
    0.5
);

const linearRamp = FillEffect.GradientLinear(
    [new Color(1, 0.5, 0, 0.8), new Color(0, 0.5, 1, 0.2)],
    0, -1, 0, 1
);

// Cascades both shader stages into a single composite FillEffect
const combinedFill = FillEffect.combine([checkerboard, linearRamp]);
const fillWgsl: string = combinedFill.compile();

import { PathGeometryUtils, ResampleModifier, WobbleModifier } from "retiam";

// 1. Decode an SVG path string to raw parametric contours
const rawContours = PathGeometryUtils.decode("M 0 0 L 100 0 L 100 100 Z");

// 2. Instantiate modifiers
const resampler = new ResampleModifier({ count: 60 });
const wobbler = new WobbleModifier({ roughness: 0.35, bowing: 0.2 });

// 3. Evaluate sequentially
const step1 = resampler.apply(rawContours);
const step2 = wobbler.apply(step1);

import { 
    PathModifierPipeline, 
    ResampleModifier, 
    WobbleModifier, 
    OffsetModifier, 
    PathGeometryUtils 
} from "retiam";

// Create a standalone pipeline
const pipeline = new PathModifierPipeline()
    .add(new ResampleModifier({ count: 50 }))
    .add(new WobbleModifier({ roughness: 0.25 }))
    .add(new OffsetModifier({ offset: 0.05 }));

const source = PathGeometryUtils.decode("M -2 -2 L 2 -2 L 2 2 L -2 2 Z");

// Initial evaluation (calculates and caches output)
const result1 = pipeline.evaluate(source);

// Second call returns cached result immediately (zero CPU cost)
const result2 = pipeline.evaluate(source);

// Mutating a modifier marks the pipeline dirty
pipeline.get(WobbleModifier)!.roughness = 0.6;
const result3 = pipeline.evaluate(source); // Re-evaluates automatically

export interface PathOptions extends EntityOptions {
    /** Path stroke shader effect (PathEffect, WGSL code string, or cascading array). */
    strokeShader?: PathEffect | string | (PathEffect | string)[];

    /** Fill shader effect (FillEffect, WGSL code string, or cascading array). */
    fillShader?: FillEffect | string | (FillEffect | string)[];

    /** Single or array of geometric path modifiers to attach in sequence. */
    modifiers?: PathModifier | PathModifier[];

    /** Use non-zero winding fill so the fill is solid at self-intersections. Default false (even-odd). */
    overlap?: boolean;

    // ... tessellation and LOD options
}

import { Path, WobbleModifier, PathEffect, Color } from "retiam";

const path = new Path("M 0 0 L 10 0", {
    modifiers: new WobbleModifier({ roughness: 0.2 }),
    strokeShader: PathEffect.Glow(0.3)
});

import { Path, Rect, Circle, ResampleModifier, WobbleModifier, PathEffect, FillEffect, Color } from "retiam";

const complexPath = new Path("M -5 0 C -5 5, 5 5, 5 0", {
    // Array of modifiers cascaded in order:
    modifiers: [
        new ResampleModifier({ count: 64 }),
        new WobbleModifier({ roughness: 0.3, bowing: 0.15 })
    ],
    // Array of cascading stroke shaders:
    strokeShader: [
        PathEffect.Gradient([new Color(0, 1, 1), new Color(1, 0, 1)]),
        PathEffect.Dashed(0.4, 0.2)
    ],
    // Fill shader:
    fillShader: FillEffect.GradientRadial(
        [new Color(1, 1, 0, 0.8), new Color(1, 0, 0, 0)],
        0, 0, 3
    )
});

// Works identically on geometric primitives (Rect, Circle, Ellipse)
const handDrawnBox = new Rect(4, 2.5, {
    modifiers: new WobbleModifier({ roughness: 0.25 }),
    strokeShader: PathEffect.Chalk()
});

